# Generated by manage.py generate_test_cases.
from datetime import timedelta

from django.contrib.auth import get_user_model
from django.db import IntegrityError
from django.utils import timezone

from bloomerp.models.auth.oauth import OAuthAccessToken
from bloomerp.oauth import hash_oauth_secret
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ModelScenario,
    ExpectedModelException,
)


class TestOAuthAccessTokenModel(BloomerpModelTestCase):
    """Exercise OAuth access-token persistence and ownership constraints."""

    model = OAuthAccessToken

    def setUp(self) -> None:
        """Create the account referenced by each token scenario."""
        self.user = get_user_model().objects.create_user(
            username="oauth-token-owner", password="test-password"
        )
        self.raw_token = "blp_oauth_example-secret"

    def _token_fields(self) -> dict[str, object]:
        """Build a complete access-token record with only its secret digest."""
        return {
            "token_hash": hash_oauth_secret(self.raw_token),
            "user": self.user,
            "client_id": "registered-client",
            "resource": "https://bloomerp.example/mcp",
            "scope": "mcp:tools",
            "expires_at": timezone.now() + timedelta(hours=12),
        }

    def _create_existing_token(self) -> None:
        """Seed an existing token for uniqueness scenarios."""
        OAuthAccessToken.objects.create(**self._token_fields())

    def _distinct_token_fields(self) -> dict[str, object]:
        """Build a second token with the same owner but a different digest."""
        return {
            **self._token_fields(),
            "token_hash": hash_oauth_secret("blp_oauth_other-secret"),
        }

    def _created_token_is_scoped(self, token: OAuthAccessToken) -> bool:
        """Check owner, audience, scope, expiration, and secret hashing."""
        return (
            token.user_id == self.user.pk
            and token.client_id == "registered-client"
            and token.resource == "https://bloomerp.example/mcp"
            and token.scope == "mcp:tools"
            and token.expires_at > timezone.now()
            and token.revoked_at is None
            and token.token_hash == hash_oauth_secret(self.raw_token)
            and self.raw_token not in token.token_hash
        )

    def _revocation_is_persisted(self, token: OAuthAccessToken) -> bool:
        """Confirm an update stores the revocation timestamp on the same token."""
        return token.revoked_at is not None and OAuthAccessToken.objects.count() == 1

    def _deleted_token_is_gone(self, token: OAuthAccessToken) -> bool:
        """Confirm deleting a token removes its database row."""
        return not OAuthAccessToken.objects.filter(pk=token.pk).exists()

    def _distinct_token_is_stored(self, token: OAuthAccessToken) -> bool:
        """Confirm distinct token digests can belong to the same user."""
        return token.user_id == self.user.pk and OAuthAccessToken.objects.count() == 2

    def get_test_scenarios(self) -> list[ModelScenario[OAuthAccessToken]]:
        """Cover creation, revocation, deletion, and digest uniqueness."""
        return [
            ModelScenario(
                name="Scoped token is stored, revoked, and deleted",
                create_args=self._token_fields,
                create_validators=self._created_token_is_scoped,
                update_args={"revoked_at": timezone.now()},
                update_validators=self._revocation_is_persisted,
                delete_validators=self._deleted_token_is_gone,
            ),
            ModelScenario(
                name="Duplicate token digest is rejected",
                preparation=self._create_existing_token,
                create_args=self._token_fields,
                expected_exceptions=[
                    ExpectedModelException(phase="create", exception=IntegrityError)
                ],
            ),
            ModelScenario(
                name="Distinct token digest is accepted",
                preparation=self._create_existing_token,
                create_args=self._distinct_token_fields,
                create_validators=self._distinct_token_is_stored,
            ),
        ]

    def test_deleting_owner_removes_token(self) -> None:
        """Ensure a removed account cannot leave an orphaned access token."""
        token = OAuthAccessToken.objects.create(**self._token_fields())
        token_pk = token.pk
        self.user.delete()
        self.assertFalse(OAuthAccessToken.objects.filter(pk=token_pk).exists())
